//! 📥️ Ordered typed image reconstruction without native format parsing.
use super::*;
fn octets(database: &SqliteDatabase, table: &str, control: &mut SqliteSnapshotControl<'_>) -> Result<Vec<u8>> { let rows = ordered(database.table(table)?,control)?; let mut bytes = allocate(rows.len(),control)?; for (index,row) in rows.iter().enumerate() { bytes.push(uint(row,3,255)? as u8); if index % 256 == 0 { control.checkpoint(RECONSTRUCT,index,rows.len())?; } } Ok(bytes) }
pub(crate) fn reconstruct(database: &SqliteDatabase, control: &mut SqliteSnapshotControl<'_>) -> Result<BmpSnapshot> {
 validate_sqlite_database_schema_controlled(database,SQL,RECONSTRUCT,control)?; control.check_database(database,RECONSTRUCT)?;
 let row = database.table("bmp_image")?.single_row()?;
 if row.rowid != 1 || row.integer(0)? != 1 { return Err(invalid("BMP image identity must be one")); }
 let schema = reconstruct_text(control,row.text(1)?)?;
 let row_order = match row.text(4)? { "bottomUp" => BmpRowOrder::BottomUp, "topDown" => BmpRowOrder::TopDown, _ => return Err(invalid("BMP unknown row order")) };
 let profile = match row.text(5)? { "indexedRgb1" => BmpProfile::IndexedRgb1, "indexedRgb4" => BmpProfile::IndexedRgb4, "indexedRgb8" => BmpProfile::IndexedRgb8, "directRgb16" => BmpProfile::DirectRgb16, "directRgb24" => BmpProfile::DirectRgb24, "directRgb32" => BmpProfile::DirectRgb32, "directBitfields16" => BmpProfile::DirectBitfields16, "directBitfields32" => BmpProfile::DirectBitfields32, _ => return Err(invalid("BMP unknown native profile")) };
 let palette_rows = ordered(database.table("bmp_palette_entry")?,control)?; let mut palette = allocate(palette_rows.len(),control)?;
 for (index,row) in palette_rows.iter().enumerate() { palette.push(BmpPaletteEntry { b:uint(row,3,255)? as u8,g:uint(row,4,255)? as u8,r:uint(row,5,255)? as u8,reserved:uint(row,6,255)? as u8 }); if index % 256 == 0 { control.checkpoint(RECONSTRUCT,index,palette_rows.len())?; } }
 let indexed = ordered(database.table("bmp_pixel_index")?,control)?; let direct = ordered(database.table("bmp_pixel_sample")?,control)?;
 let pixels = if profile.is_indexed() { if !direct.is_empty() { return Err(invalid("BMP indexed image contains direct samples")); } let mut indices = allocate(indexed.len(),control)?; for (index,row) in indexed.iter().enumerate() { indices.push(uint(row,3,255)? as u8); if index % 256 == 0 { control.checkpoint(RECONSTRUCT,index,indexed.len())?; } } BmpPixels::Indexed { indices } } else { if !indexed.is_empty() { return Err(invalid("BMP direct image contains indexed samples")); } let mut samples = allocate(direct.len(),control)?; for (index,row) in direct.iter().enumerate() { samples.push(BmpNativeSample { red:uint(row,3,u32::MAX)?,green:uint(row,4,u32::MAX)?,blue:uint(row,5,u32::MAX)?,alpha:uint(row,6,u32::MAX)?,reserved:uint(row,7,u32::MAX)? }); if index % 256 == 0 { control.checkpoint(RECONSTRUCT,index,direct.len())?; } } BmpPixels::Direct { samples } };
 let image = BmpImage { width:uint(row,2,i32::MAX as u32)?,height:uint(row,3,i32::MAX as u32)?,row_order,profile,masks:[uint(row,6,u32::MAX)?,uint(row,7,u32::MAX)?,uint(row,8,u32::MAX)?,uint(row,9,u32::MAX)?],palette,pixels,x_pixels_per_meter:signed(row,10)?,y_pixels_per_meter:signed(row,11)?,colors_used:uint(row,12,u32::MAX)?,colors_important:uint(row,13,u32::MAX)?,reserved_1:uint(row,14,65535)? as u16,reserved_2:uint(row,15,65535)? as u16,opaque_gap:octets(database,"bmp_gap_octet",control)?,opaque_trailer:octets(database,"bmp_trailer_octet",control)? };
 let snapshot = BmpSnapshot { schema,image }; snapshot.validate().map_err(invalid)?; Ok(snapshot)
}
